import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"我的最愛","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/user-guide/settings/favorites.md","filePath":"zh-TW/user-guide/settings/favorites.md","lastUpdated":1785993908000}'),s={name:"zh-TW/user-guide/settings/favorites.md"};function n(i,t,l,d,h,g){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="我的最愛" tabindex="-1">我的最愛 <a class="header-anchor" href="#我的最愛" aria-label="Permalink to &quot;我的最愛&quot;">​</a></h1><p>把常用的資料夾、檔案或網址固定下來，一個按鍵就能到達。</p><h2 id="新增最愛" tabindex="-1">新增最愛 <a class="header-anchor" href="#新增最愛" aria-label="Permalink to &quot;新增最愛&quot;">​</a></h2><ul><li><strong>顯示名稱</strong> —— 可選;如果留空且目標是本機路徑，會自動用路徑的檔案名稱填入。</li><li><strong>目標路徑</strong> —— 本機路徑，或者 <code>http://</code>/<code>https://</code> 網址。</li><li><strong>瀏覽資料夾</strong> / <strong>瀏覽檔案</strong> 按鈕 —— 開啟原生選擇器，不用手動輸入路徑。</li><li><strong>新增</strong> 按鈕 —— 輸入路徑後才可用。</li></ul><h2 id="管理清單" tabindex="-1">管理清單 <a class="header-anchor" href="#管理清單" aria-label="Permalink to &quot;管理清單&quot;">​</a></h2><p>清單裡每一條最愛都顯示名稱和目標路徑，每行帶獨立操作:</p><ul><li><strong>向上移動</strong> / <strong>向下移動</strong> —— 調整順序，同時也會影響該最愛項目在搜尋結果裡相對其他結果的排名。每一行也可以直接拖曳左邊的六點式拖曳把手來調整順序——設定裡所有可排序清單(結果類型優先權、快速導覽順序、側邊欄篩選順序、結果表格欄順序)用的都是同一個拖曳把手。</li><li><strong>編輯此項</strong> —— 把該項載入回上方輸入框以便修改。</li><li><strong>刪除此項</strong> —— 移除。</li></ul><h2 id="最愛項目如何出現在搜尋裡" tabindex="-1">最愛項目如何出現在搜尋裡 <a class="header-anchor" href="#最愛項目如何出現在搜尋裡" aria-label="Permalink to &quot;最愛項目如何出現在搜尋裡&quot;">​</a></h2><p>命中的最愛項目會在結果裡帶一個 <strong>★</strong> 標記，緊跟在資料夾/路徑標籤旁邊，並且可以用它的顯示名稱搜尋到——如果名稱裡含中文，同樣支援拼音，和其他任何結果一樣。這是 Lertaro 裡最接近「自訂搜尋別名」的功能，參見<a href="./../search-syntax.html#我的最愛-而非自訂別名">搜尋語法</a>。</p>',9)])])}const _=a(s,[["render",n]]);export{u as __pageData,_ as default};
